  function temporalStatusParts(){const parts=[];if(!appState.player)return parts;for(const e of temporalEffects()){for(const action of e.actions||[]){const label=temporalActionLabel(action);parts.push(e.remaining==null?`🕑 ${label} a cada turno`:`🕑 ${label} daqui ${e.remaining} ${e.remaining===1?'turno':'turnos'}`);}}return parts;}
