    m=v.match(/^\{([+-])\s*(.+)\}$/i);if(m){const meta=itemMeta(m[2].trim()),isProvision=/^provisão$/i.test(meta.name);if(m[1]==='+'){if(isProvision){const added=addQuantity('Provisão',1);appState.effects.push({text:added?`ADQUIRIU: Provisão ×${p.provisions}`:'CARGA CHEIA: Provisão',loss:false});}else{const added=addQuantity(meta.raw,1,{narrativeDiscovery:true,narrativeSource:'tempo'});appState.effects.push({text:added?`ADQUIRIU: ${effectInventoryDisplayName(meta)}${itemCount(meta.raw)>1?` ×${itemCount(meta.raw)}`:''}`:`CARGA CHEIA: ${meta.name}`,loss:false});}}else{if(isProvision){const removed=p.provisions>0;if(removed){p.provisions--;journalRecordItem('Provisão',1,'remove');markRuntimeChanged();}appState.effects.push({text:removed?`REMOVEU: Provisão · RESTAM ×${p.provisions}`:'ITEM AUSENTE: Provisão',loss:true});}else{const removed=removeOneItem(meta.raw);appState.effects.push({text:removed?`REMOVEU: ${effectInventoryDisplayName(meta)}`:`ITEM AUSENTE: ${meta.name}`,loss:true});}}return;}
