    if((sec.knowledges||[]).length){const p=ensureKnowledgeState();appState.appliedSectionEffects.push({kind:'knowledgeSnapshot',knowledges:deepClone(p.knowledges),knowledgeBoost:p.knowledgeBoost,knowledgeBoostTurns:p.knowledgeBoostTurns});for(const name of sec.knowledges){const result=acquireKnowledge(name),text=knowledgeGainText(result);if(text)appState.effects.push({text,loss:result.kind==='collapse'||result.kind==='limit'});if(narrative)noteSystemKnowledge(result,'section');}}
    for(const book of sec.books||[]){const meta=itemMeta(book.item),added=addQuantity(meta.raw,1,{narrativeDiscovery:narrative,narrativeSource:'section'});appState.appliedSectionEffects.push({kind:'item',op:'+',item:meta.raw,qty:1,appliedQty:added});appState.effects.push({text:added?`ADQUIRIU: ${effectInventoryDisplayName(meta)}`:`CARGA CHEIA: ${meta.name}`,loss:false});}
