  function auraActive(){return (appState.player?.auraTurns||0)>0;}
  function tickAuraTurn(){const p=appState.player;if(!p||!p.auraTurns)return;p.auraTurns=Math.max(0,p.auraTurns-1);if(p.auraTurns===0)toast('A Aura se dissipou.');}
  function tickPoisonEffect(){const p=ensureTimeState();if(!p)return;if(!hasState('Envenenado')){p.poisonEffect=null;return;}const fx=p.poisonEffect;if(!fx)return;fx.remaining=Math.max(0,(Number(fx.remaining)||1)-1);if(fx.remaining>0)return;const lost=spendEnergy(1);if(lost)queueFx('energyDown','VENENO','-1 VIDA');fx.interval=secureDie();fx.remaining=fx.interval;if(p.stamina<=0)queueFx('death','MORTE','O veneno consumiu sua última VIDA.');}
