  function loseEnergy(amount,reason=''){const p=appState.player,loss=Math.max(0,+amount||0);if(!p||loss<=0)return 0;if(auraActive()){queueFx('luckWin','AURA PROTEGEU',`${loss} VIDA evitada`);return 0;}const finalLoss=applyArmorProtection(loss);const before=p.stamina;p.stamina=Math.max(0,p.stamina-finalLoss);return before-p.stamina;}
  function spendEnergy(amount){const p=appState.player,loss=Math.max(0,+amount||0);if(!p||loss<=0)return 0;const before=p.stamina;p.stamina=Math.max(0,p.stamina-loss);return before-p.stamina;}
  function changePlayerStat(key,delta,beforeValue=null){const p=ensurePlayerStats(),before=beforeValue??p[key];markRuntimeChanged();if(key==='stamina'){if(delta<0)loseEnergy(-delta);else p.stamina=Math.min(p.initialStamina,p.stamina+delta);}else if(key==='magic'){if(delta<0)spendMagic(-delta);else recoverMagic(delta);}else p[key]=Math.max(0,p[key]+delta);if(key==='luck'&&p[key]<=0)breakLuckAmuletIfDepleted();return p[key]-before;}


  /* v212 — Economia nativa de SANIDADE: Prazer + recomposição universal. */
  /* v210 — Diretor de SANIDADE. Os episódios são internos ao motor e independentes do Markdown. */
  const SANITY_WHISPERS=[
    '{NOME}, vire-se.','{NOME}, eles sabem onde você está.','{NOME}, você deixou alguma coisa para trás.','{NOME}, pare de fingir que não me ouve.','{NOME}, isso já aconteceu antes.','{NOME}, saia daqui.','{NOME}, fique em silêncio.','{NOME}, você se lembra de mim?','{NOME}, não confie no que está vendo.','{NOME}, continue andando. Não olhe para trás.'
  ];
  const SANITY_MONSTERS=['A Sombra','O Homem sem Rosto','Seu Duplo','A Coisa que Rasteja','A Figura Atrás de Você','A Criança sem Olhos','O Animal Impossível','A Massa de Mãos'];
  const SANITY_ILLUSIONS=[
    {id:'reflexo',title:'O Reflexo Atrasado',loop:true,trap:0,variants:[
      `Você percebe uma pessoa diante de você.\n\nPor um instante parece perfeitamente normal, até que entende que está olhando para si mesmo.\n\nVocê ergue a mão. O reflexo permanece imóvel. Alguns segundos depois, ele ergue a própria mão também.\n\nEntão sorri.\n\nVocê ainda não sorriu.\n\n— Você está ficando lento, {NOME}.`,
      `Você percebe uma pessoa diante de você.\n\nÉ você outra vez. Há uma certeza desagradável de que já tocou aquela superfície antes.\n\nO reflexo parece aliviado ao vê-lo.\n\n— Voltou, {NOME}.`,
      `A superfície está diante de você novamente. Seus dedos parecem frios antes mesmo de tocá-la.\n\nO reflexo inclina a cabeça.\n\n— Quantas vezes ainda vamos trocar de lugar, {NOME}?`
    ],choices:[['Tocar o reflexo','Afastar-se dele']],resolutions:[`A superfície cede como pele fria. Uma mão segura a sua pelo outro lado e puxa com força. Por um instante você tem certeza de ter atravessado para o lugar onde o reflexo estava.`,`Você recua. O reflexo permanece imóvel. Então ele dá um passo em sua direção, embora você continue se afastando.`]},
    {id:'cadeiras',title:'As Cadeiras',text:`Quando percebe, existem cadeiras ao seu redor.\n\nDezenas delas. Todas vazias. Todas voltadas para você.\n\nUma cadeira começa a bater contra o chão como se alguém invisível estivesse aplaudindo. Outra responde. Logo toda a sala ressoa com uma salva de palmas produzida por pessoas que você não consegue ver.\n\nAs palmas cessam ao mesmo tempo.\n\nUma voz cochicha:\n\n— Agora faça alguma coisa interessante.`,choices:[['Perguntar quem está ali','Derrubar uma das cadeiras']],resolutions:[`Todas as palmas param. Uma voz responde, muito perto: — Você sabe.`,`A cadeira cai. O assento afunda por um instante, como se alguém invisível acabasse de se levantar.`]},
    {id:'nome',title:'Seu Nome',text:`— {NOME}.\n\nVocê olha ao redor.\n\n— {NOME}.\n\nA voz está mais próxima.\n\n— {NOME}.\n\nAgora parece vir exatamente de trás da sua cabeça.\n\nVocê tenta ignorá-la.\n\n— {NOME}.\n\nDesta vez percebe algo pior.\n\nA voz é sua.`,choices:[['Responder à voz','Ordenar que ela se cale']],resolutions:[`— Finalmente — responde sua própria voz.`,`— Foi você quem começou a falar comigo — responde a voz.`]},
    {id:'outra-versao',title:'A Outra Versão',text:`Alguém está esperando por você.\n\nÉ você.\n\nAs mesmas feições. As mesmas roupas. As mesmas marcas.\n\nA outra versão parece exausta.\n\n— Finalmente.\n\nEla olha para algum ponto atrás de você.\n\n— Desta vez, tente sobreviver mais tempo.\n\nVocê pergunta do que está falando.\n\nEla apenas balança a cabeça.\n\n— Você sempre pergunta isso.`,choices:[['Perguntar como você morreu','Exigir que prove quem é']],resolutions:[`— Do mesmo jeito que vai morrer desta vez.`,`Seu duplo menciona uma lembrança íntima com uma precisão impossível. Você reconhece cada detalhe e, ao mesmo tempo, tem certeza de que aquilo jamais aconteceu.`]},
    {id:'corredor',title:'O Corredor',loop:true,trap:0,variants:[
      `Existe um corredor diante de você.\n\nVocê começa a atravessá-lo. A extremidade parece próxima, mas cada passo torna o corredor ligeiramente mais comprido.\n\nVocê acelera. Ele cresce. Você corre. Ele continua crescendo.\n\nEntão percebe uma figura parada muito longe, na outra extremidade.\n\nÉ você.\n\nA figura também está correndo. Na sua direção.`,
      `Existe um corredor diante de você.\n\nSeus músculos já parecem cansados, embora você mal tenha começado.\n\nAo longe, alguém corre em sua direção. É você.\n\nDesta vez, ele também parece cansado.`,
      `O corredor continua diante de você.\n\nVocê já conhece cada passo, cada distância impossível. Seu outro eu corre na direção contrária com o mesmo cansaço nos olhos.\n\nNenhum dos dois parece capaz de chegar ao fim.`
    ],choices:[['Correr ao encontro dele','Parar e esperar']],resolutions:[`Você corre. A distância se alonga outra vez, como se o corredor estivesse sendo criado à frente dos seus pés.`,`Seu outro eu continua correndo. Quanto mais se aproxima, mais lentamente se move, até ficar imóvel diante de você. — Finalmente aprendemos alguma coisa.`]},
    {id:'contagem',title:'A Contagem',loop:true,trap:0,variants:[
      `Uma voz começa a contar.\n\n— Dez.\n— Nove.\n— Oito.\n— Sete.\n— Seis.\n\nEntão para.\n\nSilêncio.\n\nBem junto ao seu ouvido, a voz pergunta:\n\n— Quer saber o que acontece quando eu chegar a zero, {NOME}?`,
      `— Dez.\n\nVocê sabe que já ouviu esse número.\n\nA voz prossegue lentamente, satisfeita com a sua atenção.\n\n— Nove. Oito. Sete...`,
      `— Dez.\n\nA voz parece sorrir entre um número e outro.\n\n— Você continua esperando, {NOME}. Isso facilita muito.`
    ],choices:[['Esperar pelo zero','Interromper a contagem']],resolutions:[`A contagem chega a zero. Há um segundo de silêncio absoluto. Então a voz recomeça: — Dez.`,`Você fala por cima da voz. Ela se cala no meio de um número e, pela primeira vez, parece ter sido surpreendida.`]},
    {id:'esqueceu',title:'Algo Ficou Para Trás',text:`Uma certeza absoluta invade sua mente.\n\nVocê esqueceu alguma coisa. Algo importante.\n\nTalvez uma pessoa. Talvez um objeto. Talvez uma promessa.\n\nVocê tenta se lembrar. Quanto mais procura pela memória, mais certeza tem de que aquilo era essencial.\n\nEntão uma segunda certeza surge:\n\nVocê se lembra perfeitamente.\n\nSó está fingindo que esqueceu.`,choices:[['Tentar lembrar o que esqueceu','Voltar para procurar']],resolutions:[`Uma memória inteira surge pronta: cores, vozes e detalhes perfeitos de algo que você sabe que jamais aconteceu.`,`Você se vira para voltar e percebe que é incapaz de recordar de onde veio.`]},
    {id:'passos',title:'O Som dos Passos',text:`Você ouve passos atrás de você.\n\nUm. Dois. Três.\n\nQuando para, eles param. Quando continua, eles continuam.\n\nVocê se vira. Nada.\n\nComeça novamente.\n\nUm. Dois. Três.\n\nDesta vez você permanece completamente imóvel.\n\nOs passos continuam.\n\nE continuam se aproximando.`,choices:[['Virar-se de uma vez','Continuar imóvel']],resolutions:[`Você se vira e encontra apenas suas próprias pegadas chegando até onde está.`,`Os passos param exatamente atrás de você. Algo respira uma única vez junto à sua nuca.`]},
    {id:'porta',title:'A Porta',loop:true,trap:0,variants:[
      `Há uma porta onde antes existia apenas espaço vazio.\n\nVocê tem certeza de que ela jamais esteve ali.\n\nDo outro lado, alguém está chorando.\n\nVocê se aproxima. O choro cessa.\n\nUma voz baixa diz:\n\n— {NOME}?\n\nVocê reconhece a voz. É a sua.\n\n— Por favor, não abra.\n\nA maçaneta começa a girar pelo lado de dentro.`,
      `A porta está diante de você novamente.\n\nAntes mesmo de tocar a maçaneta, você sabe o que encontrará do outro lado.\n\nSua própria voz continua chorando.`,
      `A porta se abre alguns centímetros antes que você faça qualquer movimento.\n\nDo outro lado, seu outro eu já segura a maçaneta.\n\n— Entre. Vamos tentar de novo.`
    ],choices:[['Abrir a porta','Afastar-se dela']],resolutions:[`Você abre a porta. Do outro lado existe o mesmo lugar onde estava. Diante de você há uma porta. Atrás dela, alguém chora.`,`Você se afasta. A porta continua no mesmo lugar, ficando maior em vez de menor conforme a distância cresce.`]},
    {id:'ja-esteve',title:'Você Já Esteve Aqui',loop:true,trap:0,variants:[
      `Tudo parece familiar. Não apenas parecido. Familiar.\n\nVocê sabe exatamente o que acontecerá em seguida.\n\nUma voz falará seu nome. Você ouvirá três batidas. Depois sentirá alguém tocar seu ombro.\n\n— {NOME}.\n\nUma. Duas. Três.\n\nAlgo pousa a mão sobre seu ombro.`,
      `Você conhece esta sequência.\n\nDesta vez decide fazer algo diferente antes que ela termine. No mesmo instante, lembra-se de já ter tomado exatamente essa decisão.`,
      `Você tenta produzir um gesto imprevisível.\n\nEntão se lembra de pensar exatamente isso.\n\nA lembrança chega sempre um instante antes da escolha.`
    ],choices:[['Tentar quebrar a sequência','Deixar que tudo aconteça']],resolutions:[`Você age de forma diferente. Imediatamente se lembra de já ter feito exatamente isso.`,`Você para de resistir. Pela primeira vez acontece algo que não estava na lembrança: absoluto silêncio.`]},
    {id:'publico',title:'O Público',text:`Você percebe pessoas observando você.\n\nSeus rostos permanecem indistintos, como se sua mente recusasse cada tentativa de enxergá-los.\n\nUma delas cochicha alguma coisa. As outras riem. Outra aponta para você. Mais risadas.\n\nEntão todas ficam em silêncio.\n\nUma voz pergunta:\n\n— Ele já percebeu?\n\nOutra responde:\n\n— Ainda pensa que é real.`,choices:[['Aproximar-se delas','Perguntar o que deveria perceber']],resolutions:[`À medida que se aproxima, os rostos começam lentamente a assumir as suas próprias feições.`,`— Que nós estamos do lado de fora — responde alguém.`]},
    {id:'palavra',title:'A Palavra Errada',text:`Você tenta pensar no seu próprio nome.\n\nPor um momento, ele desapareceu.\n\nVocê sabe quem é. Lembra de acontecimentos. Lembra de escolhas. Lembra do seu rosto.\n\nMas seu nome simplesmente deixou de existir.\n\nEntão alguma coisa dentro da sua cabeça oferece outro nome.\n\nVocê sabe que aquele nome está errado. Mesmo assim, por alguns segundos, ele parece muito mais verdadeiro que {NOME}.`,choices:[['Tentar recordar seu nome verdadeiro','Aceitar o outro nome']],resolutions:[`Cada tentativa produz um nome diferente. Todos parecem quase corretos.`,`Uma voz responde imediatamente: — Bem-vindo de volta.`]},
    {id:'branco',title:'O Quarto Branco',loop:true,trap:0,variants:[
      `Tudo desaparece.\n\nExiste apenas um espaço branco sem portas, janelas ou sombras.\n\nVocê está sozinho.\n\nEntão ouve uma voz atrás de você.\n\n— Outra vez aqui?\n\nVocê se vira. Continua sozinho.\n\n— Nós já explicamos isso, {NOME}.\n\nPausa.\n\n— Você precisa parar de inventar lugares para fugir daqui.`,
      `O quarto continua branco.\n\nAgora existe uma porta. Você tem certeza de que acabou de atravessá-la e, mesmo assim, continua do mesmo lado.\n\n— De novo — comenta a voz.`,
      `Existem três versões de você diante de três portas idênticas.\n\nCada uma parece convencida de que as outras duas são parte do problema.`
    ],choices:[['Abrir a porta','Recusar-se a sair']],resolutions:[`Há outro quarto branco. No centro dele está você, diante de uma porta.`,`Você se senta. A voz fica em silêncio. Lentamente, as paredes começam a perder os contornos.`]},
    {id:'conversa',title:'A Conversa Interrompida',text:`Você percebe que alguém está falando com você.\n\nA conversa aparentemente já dura algum tempo.\n\n— ...e foi aí que tudo começou.\n\nVocê tenta lembrar quem é aquela pessoa. Seu rosto parece familiar.\n\n— Você realmente não se lembra de mim? Depois de tudo?\n\nVocê tenta responder.\n\nA figura leva um dedo aos lábios.\n\n— Quieto. Eles estão ouvindo você pensar.`,choices:[['Perguntar quem está ouvindo','Tentar pensar em outra coisa']],resolutions:[`— Eles. A figura olha diretamente para algum ponto além de você.`,`— Isso. Continue fingindo que você escolhe o que pensa.`]},
    {id:'corpo',title:'O Corpo Adiante',text:`Há alguém caído à frente.\n\nVocê se aproxima lentamente.\n\nA pessoa usa suas roupas. Seu equipamento. Seu rosto.\n\nVocê observa seu próprio corpo imóvel.\n\nEntão os olhos se abrem.\n\nSua própria voz sai da boca:\n\n— Demorou bastante.\n\nO corpo inspira profundamente.\n\n— Agora é a minha vez.`,choices:[['Impedir que ele se levante','Perguntar o que ele quer']],resolutions:[`Você o segura. Ele segura você exatamente da mesma forma, como um espelho com força própria.`,`— Continuar de onde você parou.`]},
    {id:'vozes',title:'As Vozes Debatem',text:`Duas vozes começam a discutir dentro da sua cabeça.\n\n— Agora.\n— Ainda é cedo.\n— Ele está fraco.\n— Ele sempre fica fraco.\n\nVocê tenta interrompê-las. As duas se calam.\n\nDepois de alguns segundos, uma delas pergunta:\n\n— Você ouviu isso?\n\nA outra responde:\n\n— Sim.\n\nPausa.\n\n— Então ele também consegue nos ouvir.`,choices:[['Perguntar quem são','Tentar expulsá-las da mente']],resolutions:[`— Ele ainda acha que nós somos duas.`,`As duas começam a rir simultaneamente com a sua própria voz.`]},
    {id:'canto',title:'A Coisa no Canto do Olho',text:`Há alguma coisa acompanhando você.\n\nEla só aparece no limite da visão. Quando olha diretamente, desaparece.\n\nVocê tenta surpreendê-la. Nada.\n\nOlha para frente novamente. Agora está mais próxima.\n\nVocê vira depressa. Nada.\n\nQuando retorna o olhar, uma voz sussurra:\n\n— Continue fazendo isso. Está funcionando.`,choices:[['Fechar os olhos','Fixar os olhos no ponto onde ela aparece']],resolutions:[`— Muito melhor. A voz vem de perto demais.`,`Você percebe que existe alguma coisa entre você e o ponto que estava tentando observar.`]},
    {id:'todos',title:'Todos São Você',text:`Uma pessoa passa por você.\n\nEla tem seu rosto.\n\nOutra aparece. Também tem seu rosto.\n\nEntão outra. E outra.\n\nTodas são você. Nenhuma parece surpresa.\n\nUma delas para. Observa você cuidadosamente.\n\n— Este acha que é o original.\n\nAs outras começam a rir.`,choices:[['Perguntar qual deles é o original','Escolher um deles e confrontá-lo']],resolutions:[`Todos apontam simultaneamente para outra pessoa. Nenhum aponta para você.`,`Seu duplo sorri: — Eu fiz isso também na primeira vez.`]},
    {id:'pensamento',title:'O Pensamento Estranho',text:`Um pensamento surge em sua mente:\n\n*Não olhe para trás.*\n\nVocê sente imediatamente que aquele pensamento não pertence a você.\n\nOutro aparece:\n\n*Ele percebeu.*\n\nDepois outro:\n\n*Finja que somos pensamentos dele.*\n\nVocê tenta esvaziar a mente. Por alguns instantes funciona.\n\nEntão surge uma última frase:\n\n*Muito melhor, {NOME}. Agora podemos conversar.*`,choices:[['Responder mentalmente','Tentar pensar em absoluto silêncio']],resolutions:[`*Ele respondeu.* Outra presença pensa: *Então já conseguimos atravessar.*`,`*Ele está ouvindo.*\n\n*Finja que fomos embora.*`]},
    {id:'realidade',title:'A Realidade Errada',text:`Tudo parece perfeitamente normal.\n\nEssa é a parte mais perturbadora.\n\nNenhuma voz. Nenhuma sombra. Nenhuma figura impossível.\n\nVocê respira fundo. Talvez tenha passado.\n\nEntão uma voz dentro da sua cabeça ri.\n\n— Engraçado, {NOME}. Você realmente acha que esta é a realidade?`,choices:[['Ignorar a voz e seguir em frente','Perguntar o que é real']],resolutions:[`— Ótimo. É sempre mais fácil quando você coopera.`,`— Qual das vezes?`]},
  ];

  function freshSanityRuntime(){return {majorCooldown:0,lastRealSectionId:null,choiceImmunitySectionId:null,activeEpisode:null,illusionLoopCount:0,recentIllusions:[],pendingCritical:null,sectionIncidentToken:0,sectionIncidentRolledId:null,processingCritical:false,illusoryCombat:null,illusionView:null};}
  function ensureSanityRuntime(){if(!appState.sanityRuntime||typeof appState.sanityRuntime!=='object')appState.sanityRuntime=freshSanityRuntime();const r=appState.sanityRuntime,base=freshSanityRuntime();for(const [k,v] of Object.entries(base))if(r[k]===undefined)r[k]=v;if(!Array.isArray(r.recentIllusions))r.recentIllusions=[];return r;}
  function resetSanityRuntime(){appState.sanityRuntime=freshSanityRuntime();return appState.sanityRuntime;}
  function sanityRuntimeForSave(){const r=ensureSanityRuntime();return {majorCooldown:Math.max(0,Number(r.majorCooldown)||0),lastRealSectionId:r.lastRealSectionId||null,choiceImmunitySectionId:r.choiceImmunitySectionId||null,recentIllusions:(r.recentIllusions||[]).slice(-6)};}
  function restoreSanityRuntime(saved){const r=resetSanityRuntime(),src=saved&&typeof saved==='object'?saved:{};r.majorCooldown=Math.max(0,Number(src.majorCooldown)||0);r.lastRealSectionId=src.lastRealSectionId||appState.sectionId||null;r.choiceImmunitySectionId=src.choiceImmunitySectionId||null;r.recentIllusions=Array.isArray(src.recentIllusions)?src.recentIllusions.slice(-6):[];return r;}
  function sanityValue(){return Number(appState.player?.magic)||0;}
  function sanityRandom(){try{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296;}catch{return Math.random();}}
  function sanityPick(list){return list?.length?list[Math.floor(sanityRandom()*list.length)]:null;}
  function sanityDie(sides=6){return 1+Math.floor(sanityRandom()*Math.max(1,sides));}
  function sanityIncidentEligible(){return !!(appState.book&&appState.player&&appState.player.stamina>0&&appState.adventureStarted&&!appState.editor&&!appState.premonition&&!adventureEnded()&&!appState.deathFlowActive&&!appState.deathPresentationPending);}
  function sanityOverlayVisible(){return !el('sanityOverlay')?.classList.contains('hidden');}
  function sanityBusySurface(){return sanityOverlayVisible()||!el('rewardOverlay')?.classList.contains('hidden')||!el('dreamOverlay')?.classList.contains('hidden')||!el('diceOverlay')?.classList.contains('hidden')||!!document.querySelector('dialog[open]')||appState.pageTurning||appState.fxBusy||appState.temporalBusy||appState.sleepBusy||appState.hungerBusy||appState.quickCombatBusy;}
  function sanityMajorAllowed(){const r=ensureSanityRuntime();return sanityIncidentEligible()&&!r.activeEpisode&&r.majorCooldown<=0;}
  function markSanityMajorIncident(){const r=ensureSanityRuntime();r.majorCooldown=3;r.choiceImmunitySectionId=appState.sectionId||null;}
  function changeSanity(delta,source=''){const p=appState.player;if(!p)return 0;const d=Number(delta)||0,before=Number(p.magic)||0;if(!d)return 0;p.magic=d>0?Math.min(Math.max(0,Number(p.initialMagic)||0),before+d):before+d;const actual=p.magic-before;if(!ensureSanityRuntime().activeEpisode&&actual<0){const r=ensureSanityRuntime();r.pendingCritical=p.magic<0?'rupture':p.magic===0?'collapse':r.pendingCritical;if(r.pendingCritical)scheduleSanityCritical();}return actual;}
  function scheduleSanityCritical(delay=120){const r=ensureSanityRuntime();if(!r.pendingCritical||r.processingCritical||r.activeEpisode)return;setTimeout(()=>processSanityPendingCritical(),Math.max(40,delay));}
  async function processSanityPendingCritical(){const r=ensureSanityRuntime();if(r.processingCritical||r.activeEpisode||!r.pendingCritical||!appState.player)return;if(sanityBusySurface()){scheduleSanityCritical(180);return;}const kind=sanityValue()<0?'rupture':sanityValue()===0?'collapse':null;if(!kind){r.pendingCritical=null;return;}r.processingCritical=true;r.pendingCritical=null;try{if(kind==='rupture')await triggerSanityRupture();else await triggerSanityCollapse();}finally{r.processingCritical=false;}}

  function showSanityOverlay({icon='🧠',title='SANIDADE BAIXA',headline='',detail='',story='',actions=[{id:'continue',label:'Continuar',kind:'primary'}],episode=false}={}){
    return new Promise(resolve=>{primeAudio();const overlay=el('sanityOverlay'),card=el('sanityCard'),box=el('sanityActions');if(!overlay||!card||!box){resolve(actions[0]?.id||'continue');return;}card.classList.toggle('episode',!!episode);el('sanityIcon').textContent=icon;el('sanityTitle').textContent=title;el('sanityHeadline').textContent=headline;const detailBox=el('sanityDetail');detailBox.textContent=detail;detailBox.classList.toggle('hidden',!detail);const storyBox=el('sanityStory');storyBox.innerHTML=story?renderMarkdownText(heroText(story)):'';storyBox.classList.toggle('hidden',!story);box.innerHTML='';box.classList.toggle('one',actions.length<=1);let settled=false;const finish=id=>{if(settled)return;settled=true;overlay.classList.add('hidden');box.innerHTML='';storyBox.innerHTML='';card.classList.remove('episode');if(appState.readingAssistEnabled)scheduleVoiceCycle(true,160);resolve(id);};for(const a of actions){const b=document.createElement('button');b.type='button';b.className=a.kind==='danger'?'danger-btn':a.kind==='secondary'?'secondary-btn':'primary-btn';b.textContent=a.label;b.onclick=()=>finish(a.id);box.appendChild(b);}overlay.classList.remove('hidden');tone(210,.12,0,'triangle',.035);tone(330,.16,.08,'sine',.025);if(navigator.vibrate)navigator.vibrate([22,35,22]);if(appState.readingAssistEnabled)scheduleVoiceCycle(true,90);});
  }
  function showSanityMoment(opts={}){return showSanityOverlay({...opts,episode:false});}
