  function syncBookSectionImageReveal(img,visualImage){
    if(!img)return;
    if(!visualImage){delete img.dataset.bookRevealKey;img.classList.remove('book-image-reveal');return;}
    if(!bookModeEnabled()||appState.editor){img.classList.remove('book-image-reveal');return;}
    const key=`${appState.sectionId}|${visualImage}`;
    if(img.dataset.bookRevealKey===key)return;
    img.dataset.bookRevealKey=key;
    const reveal=()=>{
      if(img.dataset.bookRevealKey!==key||!bookModeEnabled()||appState.editor)return;
      img.classList.remove('book-image-reveal');
      void img.offsetWidth;
      img.classList.add('book-image-reveal');
    };
    if(img.complete&&img.naturalWidth)requestAnimationFrame(reveal);
    else img.addEventListener('load',()=>requestAnimationFrame(reveal),{once:true});
  }


