  function bookEffectStat(text){const m=cleanText(text).match(/^([+-])\s*(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)$/i);if(!m)return null;const label=playerStatLabel(m[3]).toLocaleLowerCase('pt-BR');return `${label.charAt(0).toLocaleUpperCase('pt-BR')+label.slice(1)} ${m[1]}${m[2]}`;}
