  function renderBookInventoryBalance(box,acquired=[],removed=[]){if(!acquired.length&&!removed.length)return;const rule=document.createElement('hr');rule.className='book-acquired-rule';box.appendChild(rule);const add=normalizeBookInventoryChange(acquired),sub=normalizeBookInventoryChange(removed);if(add.length){const note=document.createElement('span');note.className='effect book-acquired-note';note.textContent=`Adquiriu: ${add.join(', ')}`;box.appendChild(note);}if(sub.length){const note=document.createElement('span');note.className='effect book-acquired-note loss';note.textContent=`Removeu: ${sub.join(', ')}`;box.appendChild(note);}}
