  function commerceCatalogPriceForItem(raw=''){return adventureItemPrice(raw,1);}
  function mostValuableEquipment(){const entries=inventoryCounts();if(!entries.length)return null;return entries.map(entry=>({...entry,price:commerceCatalogPriceForItem(entry.meta.raw)})).sort((a,b)=>b.price-a.price||a.meta.name.localeCompare(b.meta.name,'pt-BR',{sensitivity:'base'}))[0]||null;}
  function stealIndemnity(){const p=appState.player,gold=goldCount(),provisions=Math.max(0,p?.provisions||0),parts=[];if(gold&&p?.items){for(let i=p.items.length-1;i>=0;i--)if(isGoldItem(p.items[i]))p.items.splice(i,1);recordJournal(`Perdi ${currencyAmountLabel(gold)} como indenização.`,{kind:'commerce'});markRuntimeChanged();parts.push(currencyAmountLabel(gold));}if(provisions){p.provisions=0;recordJournal(`Perdi ${provisions} ${provisions===1?'provisão':'provisões'} como indenização.`,{kind:'commerce'});markRuntimeChanged();parts.push(`${provisions} ${provisions===1?'provisão':'provisões'}`);return {dead:false,parts};}const equipment=mostValuableEquipment();if(equipment){removeOneItem(equipment.meta.raw,{journal:false});recordJournal(`Entreguei ${equipment.meta.name} como indenização.`,{kind:'commerce'});parts.push(`${equipment.meta.name} (${equipment.price} ${currencyName()} na tabela)`);return {dead:false,parts};}if(p){p.stamina=0;document.body.classList.add('fx-death');queueFx('death','MORTE','Sem recursos para pagar a indenização, sua jornada termina aqui.');}return {dead:true,parts};}
  async function attemptStealSectionCommerce(entry){const sec=appState.book?.sections?.[appState.sectionId],p=appState.player;if(!sec||!p||!canStealFromCommerce()||!entry)return;appState.commerceStealMode=false;const stealing=Math.max(0,Number(knowledgeValue('Roubar'))||0),target=Math.max(0,(Number(p.luck)||0)+stealing),result=await dramaticRoll({title:`Tentar roubar de ${commerceDisplayName(sec)}`,lead:`FORTUNA ${p.luck} + Roubar ${stealing} = alvo ${target}. Role 2d6 e obtenha ${target} ou menos para sair sem ser percebido.`,diceCount:2,evaluate:r=>{const roll=rollUnder2d6(r,target),total=roll.total,success=roll.success;return {total,equation:`${r[0]} + ${r[1]} = ${total}`,headline:roll.criticalSuccess?'ACERTO CRÍTICO':roll.criticalFailure?'FALHA CRÍTICA':success?'ROUBO BEM-SUCEDIDO':'PEGO NO FLAGRANTE',detail:success?`Você consegue esconder ${commerceEntryLabel(entry)} antes que percebam.`:'O comerciante percebe a tentativa e exige uma indenização.',success,criticalSuccess:roll.criticalSuccess,criticalFailure:roll.criticalFailure};}});if(!result){renderSectionCommerce();return;}p.luck=Math.max(0,p.luck-1);if(result.outcome.success){addQuantity(entry.item,Math.max(1,parseInt(entry.qty)||1),{force:true,silent:true});renderAll();renderSectionCommerce();await showRewardMoment({kind:'trade',title:'ROUBO',headline:commerceEntryLabel(entry).toUpperCase(),detail:'O item foi levado sem pagamento. Sua FORTUNA diminuiu em 1.',icon:'🖐️'});return;}const penalty=stealIndemnity(),detail=penalty.dead?'Você foi pego no flagrante. Todo o seu dinheiro foi confiscado. Como você já estava sem provisões e sem qualquer equipamento para entregar, a dívida custou sua vida.':`Você foi pego no flagrante e terá que pagar uma indenização. Foram confiscados: ${penalty.parts.length?penalty.parts.join(', '):'seus recursos disponíveis'}. Sua FORTUNA diminuiu em 1.`;const d=el('sectionCommerceDialog');if(d?.open)d.close();await showNotice('Pego no flagrante',detail);renderAll();}
  function renderSectionCommerce(){const sec=appState.book?.sections?.[appState.sectionId],box=el('sectionCommerceList'),dialog=el('sectionCommerceDialog'),stealBtn=el('sectionCommerceStealBtn');if(!sec||!box)return;const stealMode=!!appState.commerceStealMode&&canStealFromCommerce();if(dialog)dialog.classList.toggle('steal-mode',stealMode);const title=dialog?.querySelector('.dialog-head h2');if(title)title.textContent=stealMode?`Roubar de ${commerceDisplayName(sec)}`:`Comprar de ${commerceDisplayName(sec)}`;if(stealBtn){stealBtn.classList.toggle('hidden',!canStealFromCommerce()||!(sec.commerce||[]).length);stealBtn.textContent=stealMode?'Cancelar roubo':'Tentar roubar';}box.innerHTML='';const gold=sectionCommerceBalance(sec);for(const entry of sec.commerce||[]){const price=Math.max(1,parseInt(entry.price)||1),b=document.createElement('button');b.type='button';b.className='section-commerce-offer';const capacityBlocked=!stealMode&&currentLoad()+commercePurchaseLoad(entry)>loadLimit(),poor=!stealMode&&gold<price;b.disabled=poor||capacityBlocked;b.innerHTML=stealMode?`${esc(commerceEntryLabel(entry))}<small>tentar levar este item</small>`:`${esc(commerceEntryLabel(entry))} por ${price} ${esc(currencyName())}.${poor?'<small>(saldo insuficiente)</small>':capacityBlocked?'<small>(carga máxima)</small>':''}`;b.onclick=()=>stealMode?attemptStealSectionCommerce(entry):buySectionCommerce(entry);box.appendChild(b);}if(!box.children.length){const empty=document.createElement('div');empty.className='empty-state';empty.textContent='Este comércio está sem produtos.';box.appendChild(empty);}}
