  async function buySectionCommerce(entry){const price=Math.max(1,parseInt(entry?.price)||1),qty=Math.max(1,parseInt(entry?.qty)||1),meta=itemMeta(entry?.item||'');const sec=appState.book?.sections?.[appState.sectionId];if(!sec||!meta.name||sectionCommerceBalance(sec)<price||currentLoad()+commercePurchaseLoad(entry)>loadLimit())return;spendSectionCommerceBudget(sec,price);addQuantity(meta.raw,qty,{silent:true});renderAll();renderSectionCommerce();await showRewardMoment({kind:'trade',title:'COMPRA',headline:commerceEntryLabel(entry).toUpperCase(),detail:commerceBudgetIsMoney(sec)?`${price} ${currencyName()} foram entregues ao comerciante.`:`${price} créditos do orçamento foram usados.`,icon:'🛒'});}

  function renderSectionActions(){const s=appState.book.sections[appState.sectionId],box=el('sectionActions');box.innerHTML='';if(appState.editor||adventureEnded()||!allCombatsResolved()){box.classList.add('hidden');return;}if(s.treasure&&!sectionCombatDefs(s).length&&!appState.player.openedTreasures[appState.sectionId]){const b=document.createElement('button');b.className='section-action-btn treasure-btn';b.textContent='Abrir Tesouro';b.onclick=()=>openTreasure('section');box.appendChild(b);}for(const trade of s.trades||[]){const b=document.createElement('button');b.className='section-action-btn trade-btn';b.textContent=`Trocar ${qtyLabel(trade.from.qty,trade.from.item)} por ${qtyLabel(trade.to.qty,trade.to.item)}`;b.disabled=quantityAvailable(trade.from.item)<trade.from.qty;b.onclick=()=>executeTrade(trade);box.appendChild(b);}if((s.commerce||[]).length){const shop=document.createElement('button');shop.className='section-action-btn commerce-section-btn';shop.innerHTML=`<span class="commerce-emoji-line">💰📦</span><span class="commerce-label-line">Comprar de ${esc(commerceDisplayName(s))}</span>`;shop.onclick=openSectionCommerce;box.appendChild(shop);}box.classList.toggle('hidden',!box.children.length);}


  function thiefBypassPlan(c){
    const list=Array.isArray(c?.requirements)?c.requirements:[];if(!list.length||choiceRequirementsMet(c))return null;
    const missing=list.map((r,index)=>({r,index})).filter(x=>!requirementQuantityMet(x.r));
    if(c.requirementMode==='ANY'){const pick=missing.find(x=>requirementEditorKind(x.r.item)==='ITEM');return pick?{item:pick.r.item,requirements:[]}:null;}
    if(missing.length!==1||requirementEditorKind(missing[0].r.item)!=='ITEM')return null;
    const pick=missing[0];return {item:pick.r.item,requirements:list.filter((_,index)=>index!==pick.index)};
  }

  function premonitionTargets(){const sec=appState.book?.sections?.[appState.sectionId],out=[];if(!sec)return out;for(const c of sec.choices||[]){if(!choiceRequirementsMet(c))continue;const label=heroText(c.text||'Alternativa');if(c.type==='test'||c.type==='answer'){if(c.success&&appState.book.sections[c.success])out.push({id:c.success,label:`${label} — ${c.successLabel||'Sucesso'}`});if(c.failure&&appState.book.sections[c.failure])out.push({id:c.failure,label:`${label} — ${c.failureLabel||'Fracasso'}`});}else if(c.target&&appState.book.sections[c.target])out.push({id:c.target,label});}return out;}
